    /**
     * Method to retrieve the Deal via an DealPrimaryKey.
     * @param 	id Long
     * @return 	Deal
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Deal handle( FindDealQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDealId() );
    }
    
    /**
     * Method to retrieve a collection of all Deals
     *
     * @param	query	FindAllDealQuery 
     * @return 	List<Deal> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Deal> handle( FindAllDealQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDeal,
 * but only if the id matches
 *
 * @param		entity	Deal
 */
	protected void emitFindDeal( Deal entity ) {
		LOGGER.info("handling emitFindDeal" );
		
	    queryUpdateEmitter.emit(FindDealQuery.class,
	                            query -> query.getFilter().getDealId().equals(entity.getDealId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDeal
	 * 
	 * @param		entity	Deal
	 */
	protected void emitFindAllDeal( Deal entity ) {
		LOGGER.info("handling emitFindAllDeal" );
		
	    queryUpdateEmitter.emit(FindAllDealQuery.class,
	                            query -> true,
	                            entity);
	}

